import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { motion } from "framer-motion";
import { CalendarDays, MapPin, Clock, Users, Filter } from "lucide-react";

import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

import Navbar from "@/components/Navbar";
import Footer from "@/components/Footer";
import SectionHeading from "@/components/SectionHeading";
import type { Tables } from "@/integrations/supabase/types";

type Event = Tables<"events">;

const EVENT_TYPE_LABELS: Record<string, string> = {
  workshop: "Workshop",
  networking: "Networking",
  masterclass: "Masterclass",
  meetup: "Meetup",
  conference: "Conférence",
  webinar: "Webinaire",
};

const Events = () => {
  const [events, setEvents] = useState<Event[]>([]);
  const [filterType, setFilterType] = useState<string>("all");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchEvents = async () => {
      let query = supabase
        .from("events")
        .select("*")
        .eq("status", "published")
        .gte("date", new Date().toISOString().split("T")[0])
        .order("date", { ascending: true });

      if (filterType !== "all") {
        query = query.eq("event_type", filterType as "workshop" | "networking" | "masterclass" | "meetup" | "conference" | "webinar");
      }

      const { data } = await query;
      setEvents(data || []);
      setLoading(false);
    };
    fetchEvents();
  }, [filterType]);

  const spotsPercent = (ev: Event) => ((ev.total_places - ev.spots_left) / ev.total_places) * 100;

  return (
    <div className="min-h-screen bg-background">
      <Navbar />
      <div className="pt-24 pb-16 container mx-auto px-4">
        <SectionHeading
          badge="Événements"
          title="Rejoignez notre communauté"
          subtitle="Workshops, networking, masterclasses — il y a toujours quelque chose qui se passe à La Bulle."
        />

        {/* Filter */}
        <div className="flex items-center gap-3 mb-8 justify-center">
          <Filter size={18} className="text-muted-foreground" />
          <Select value={filterType} onValueChange={setFilterType}>
            <SelectTrigger className="w-48">
              <SelectValue placeholder="Tous les types" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Tous les types</SelectItem>
              {Object.entries(EVENT_TYPE_LABELS).map(([k, v]) => (
                <SelectItem key={k} value={k}>{v}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {loading ? (
          <div className="text-center py-16 text-muted-foreground">Chargement...</div>
        ) : events.length === 0 ? (
          <div className="text-center py-16">
            <p className="text-muted-foreground text-lg">Aucun événement à venir pour le moment</p>
            <p className="text-sm text-muted-foreground mt-2">Revenez bientôt !</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {events.map((ev, i) => (
              <motion.div
                key={ev.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.1 }}
              >
                <Link to={`/events/${ev.id}`}>
                  <div className="group rounded-2xl border border-border bg-card overflow-hidden hover:shadow-lg transition-all hover:-translate-y-1">
                    {ev.cover_image_url ? (
                      <div className="h-48 overflow-hidden">
                        <img src={ev.cover_image_url} alt={ev.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" />
                      </div>
                    ) : (
                      <div className="h-48 bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center">
                        <CalendarDays size={48} className="text-primary/40" />
                      </div>
                    )}
                    <div className="p-5">
                      <div className="flex items-center gap-2 mb-3">
                        <Badge variant="secondary">{EVENT_TYPE_LABELS[ev.event_type] || ev.event_type}</Badge>
                        {ev.price_type === "free" ? (
                          <Badge className="bg-accent text-accent-foreground border-accent">Gratuit</Badge>
                        ) : (
                          <Badge variant="outline">{ev.price_amount}€</Badge>
                        )}
                        {ev.difficulty && (
                          <Badge variant="outline" className="text-xs">{ev.difficulty}</Badge>
                        )}
                      </div>
                      <h3 className="font-heading font-bold text-lg mb-2 group-hover:text-primary transition-colors line-clamp-2">{ev.name}</h3>
                      <div className="space-y-1.5 text-sm text-muted-foreground">
                        <div className="flex items-center gap-2">
                          <CalendarDays size={14} />
                          {new Date(ev.date).toLocaleDateString("fr-FR", { weekday: "short", day: "numeric", month: "long" })}
                        </div>
                        <div className="flex items-center gap-2">
                          <Clock size={14} />
                          {ev.start_time?.slice(0, 5)}{ev.end_time ? ` - ${ev.end_time.slice(0, 5)}` : ""}
                        </div>
                        <div className="flex items-center gap-2">
                          <MapPin size={14} />
                          {ev.location}
                        </div>
                      </div>

                      {/* Spots left FOMO */}
                      <div className="mt-4">
                        <div className="flex items-center justify-between text-xs mb-1">
                          <span className="flex items-center gap-1 text-muted-foreground">
                            <Users size={12} />
                            {ev.spots_left} places restantes
                          </span>
                          <span className="text-muted-foreground">{Math.round(spotsPercent(ev))}% rempli</span>
                        </div>
                        <Progress value={spotsPercent(ev)} className="h-2" />
                        {ev.spots_left <= 5 && ev.spots_left > 0 && (
                          <p className="text-xs text-destructive font-medium mt-1">🔥 Plus que {ev.spots_left} places !</p>
                        )}
                        {ev.spots_left === 0 && (
                          <p className="text-xs text-destructive font-medium mt-1">Complet</p>
                        )}
                      </div>
                    </div>
                  </div>
                </Link>
              </motion.div>
            ))}
          </div>
        )}
      </div>
      <Footer />
    </div>
  );
};

export default Events;
